def fizzbuzz(n):
    """Return a list of strings for numbers 1..n following the FizzBuzz rules."""
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def roman_to_int(s):
    """Convert a Roman numeral string to an integer."""
    roman_values = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }

    total = 0
    i = 0

    while i < len(s):
        if i + 1 < len(s) and roman_values[s[i]] < roman_values[s[i+1]]:
            total -= roman_values[s[i]]
        else:
            total += roman_values[s[i]]
        i += 1

    return total

def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort by start time, then by end time
    intervals.sort()

    merged = []
    for start, end in intervals:
        # If the current interval overlaps with the last merged interval
        if merged and start <= merged[-1][1]:
            # Merge by updating the end of the last interval
            merged[-1][1] = max(merged[-1][1], end)
        else:
            # No overlap, add the current interval
            merged.append([start, end])

    return merged

def two_sum(nums, target):
    """
    Find a pair (i, j) with i < j such that nums[i] + nums[j] == target.
    Returns the pair with the smallest j, then the smallest i.
    Returns None if no such pair exists.
    """
    n = len(nums)
    best_j = None
    best_i = None

    for j in range(n):
        for i in range(j):
            if nums[i] + nums[j] == target:
                if best_j is None or j < best_j:
                    best_j = j
                    best_i = i
                elif j == best_j and i < best_i:
                    best_i = i

    return (best_i, best_j) if best_j is not None else None

def caesar(text, shift):
    """Shift every ASCII letter by `shift` positions in the alphabet, wrapping around."""
    result = []
    for char in text:
        if 'a' <= char <= 'z':
            shifted = (ord(char) - ord('a') + shift) % 26
            result.append(chr(shifted + ord('a')))
        elif 'A' <= char <= 'Z':
            shifted = (ord(char) - ord('A') + shift) % 26
            result.append(chr(shifted + ord('A')))
        else:
            result.append(char)
    return ''.join(result)

def is_balanced(s):
    """Check if all brackets in the string are properly balanced."""
    bracket_map = {')': '(', ']': '[', '}': '{'}
    open_brackets = set(bracket_map.values())
    stack = []

    for char in s:
        if char in bracket_map:
            # Closing bracket - check if it matches the top of stack
            if stack and stack[-1] == bracket_map[char]:
                stack.pop()
            else:
                return False
        elif char in open_brackets:
            # Opening bracket - push to stack
            stack.append(char)

    # All brackets must be matched (stack should be empty)
    return len(stack) == 0

def rle_encode(s):
    """Run-length encode a string.

    Each maximal run of the same character becomes the character followed by the run length.
    """
    if not s:
        return ''

    result = []
    current_char = s[0]
    count = 1

    for i in range(1, len(s)):
        if s[i] == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = s[i]
            count = 1

    # Append the last run
    result.append(f"{current_char}{count}")

    return ''.join(result)
